window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f6739944ea211f42"]={"versions": [{"id": "FIG-f6739944ea211f42", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion zwischen einem Software-Modul und dem Default Error Tracer (DET) in der AUTOSAR Classic Platform. Dargestellt ist der synchrone Ablauf beim Auftreten eines Laufzeitfehlers ohne aktive Weiterleitung an Integrator-Callouts.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>Det User</code>: Aufrufende BSW- oder SWC-Entität.\n</li><li><code>«module» Det</code>: Default Error Tracer als zentrales Fehlerbehandlungsmodul.\n</li><li><code>Integrator Code</code>: Empfänger möglicher Hook-Funktionen bzw. Callouts (in diesem Szenario inaktiv).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Notizen:</p>\n<ul class=\"fig-list\"><li>Synchrone Funktionsschnittstelle <code>Det_ReportRuntimeError(return, ModuleId, InstanceId, ApiId, ErrorId)</code>.\n</li><li>Rückgabewert <code>:E_OK</code>.\n</li><li>Notizsymbol mit Zuordnung <code>&lt;Det_General&gt;</code> und Bedingung <code>RuntimeError callouts NOT configured</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>Det User</code> setzt den synchronen Aufruf <code>Det_ReportRuntimeError(return, ModuleId, InstanceId, ApiId, ErrorId)</code> an das Modul <code>Det</code> ab.\n</li><li>Da gemäß Bedingung <code>&lt;Det_General&gt; RuntimeError callouts NOT configured</code> keine Callouts für Laufzeitfehler konfiguriert sind, erfolgt keine Interaktion mit <code>Integrator Code</code>.\n</li><li>Das Modul <code>Det</code> antwortet unmittelbar mit dem Rückgabewert <code>:E_OK</code> an <code>Det User</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation definiert das standardmäßige Verhalten von <code>Det_ReportRuntimeError</code>, wenn im Konfigurationszweig <code>Det_General</code> keine Callout-Routinen für Laufzeitfehler aktiviert sind. Das Modul führt keine Weiterleitung an Integrator-spezifischen Code aus und quittiert den Aufruf direkt mit <code>E_OK</code>. Für Implementierer bedeutet dies minimalen Overhead ohne Verzweigung in Anwender-Callouts.</p>"}, {"id": "FIG-8104920095fd3846", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion zwischen einem Software-Modul und dem Default Error Tracer (DET) in der AUTOSAR Classic Platform. Dargestellt ist der synchrone Ablauf beim Auftreten eines Laufzeitfehlers ohne aktive Weiterleitung an Integrator-Callouts.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>Det User</code>: Aufrufende BSW- oder SWC-Entität.\n</li><li><code>«module» Det</code>: Default Error Tracer als zentrales Fehlerbehandlungsmodul.\n</li><li><code>Integrator Code</code>: Empfänger möglicher Hook-Funktionen bzw. Callouts (in diesem Szenario inaktiv).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Notizen:</p>\n<ul class=\"fig-list\"><li>Synchrone Funktionsschnittstelle <code>Det_ReportRuntimeError(return, ModuleId, InstanceId, ApiId, ErrorId)</code>.\n</li><li>Rückgabewert <code>:E_OK</code>.\n</li><li>Notizsymbol mit Zuordnung <code>&lt;Det_Notification&gt;</code> und Bedingung <code>RuntimeError callouts NOT configured</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>Det User</code> setzt den synchronen Aufruf <code>Det_ReportRuntimeError(return, ModuleId, InstanceId, ApiId, ErrorId)</code> an das Modul <code>Det</code> ab.\n</li><li>Da gemäß Bedingung <code>&lt;Det_Notification&gt; RuntimeError callouts NOT configured</code> keine Callouts für Laufzeitfehler konfiguriert sind, erfolgt keine Interaktion mit <code>Integrator Code</code>.\n</li><li>Das Modul <code>Det</code> antwortet unmittelbar mit dem Rückgabewert <code>:E_OK</code> an <code>Det User</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation definiert das standardmäßige Verhalten von <code>Det_ReportRuntimeError</code>, wenn im Konfigurationszweig <code>Det_Notification</code> keine Callout-Routinen für Laufzeitfehler konfiguriert sind. Das Modul führt keine Weiterleitung an Integrator-spezifischen Code aus und quittiert den Aufruf direkt mit <code>E_OK</code>. Für Implementierer bedeutet dies minimalen Overhead ohne Verzweigung in Anwender-Callouts.</p>"}, {"id": "FIG-81b32993bfffabb0", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion zwischen einem Software-Modul und dem Default Error Tracer (DET) in der AUTOSAR Classic Platform. Dargestellt ist der synchrone Ablauf beim Auftreten eines Laufzeitfehlers ohne aktive Weiterleitung an Integrator-Callouts.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>Det User</code>: Aufrufende BSW- oder SWC-Entität.\n</li><li><code>«module» Det</code>: Default Error Tracer als zentrales Fehlerbehandlungsmodul.\n</li><li><code>Integrator Code</code>: Empfänger möglicher Hook-Funktionen bzw. Callouts (in diesem Szenario inaktiv).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Notizen:</p>\n<ul class=\"fig-list\"><li>Synchrone Funktionsschnittstelle <code>Det_ReportRuntimeError(return, ModuleId, InstanceId, ApiId, ErrorId)</code>.\n</li><li>Rückgabewert <code>:E_OK</code>.\n</li><li>Notizsymbol mit Zuordnung <code>&lt;Det_Notification&gt;</code> und Bedingung <code>RuntimeError callouts NOT configured</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>Det User</code> setzt den synchronen Aufruf <code>Det_ReportRuntimeError(return, ModuleId, InstanceId, ApiId, ErrorId)</code> an das Modul <code>Det</code> ab.\n</li><li>Da gemäß Bedingung <code>&lt;Det_Notification&gt; RuntimeError callouts NOT configured</code> keine Callouts für Laufzeitfehler konfiguriert sind, erfolgt keine Interaktion mit <code>Integrator Code</code>.\n</li><li>Das Modul <code>Det</code> antwortet unmittelbar mit dem Rückgabewert <code>:E_OK</code> an <code>Det User</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation definiert das standardmäßige Verhalten von <code>Det_ReportRuntimeError</code>, wenn im Konfigurationszweig <code>Det_Notification</code> keine Callout-Routinen für Laufzeitfehler konfiguriert sind. Das Modul führt keine Weiterleitung an Integrator-spezifischen Code aus und quittiert den Aufruf direkt mit <code>E_OK</code>. Für Implementierer bedeutet dies minimalen Overhead ohne Verzweigung in Anwender-Callouts.</p>"}], "trans": [{"from": "FIG-f6739944ea211f42", "to": "FIG-8104920095fd3846", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Notizfeld: Konfigurationscontainer-Referenz von <code>&lt;Det_General&gt;</code> zu <code>&lt;Det_Notification&gt;</code> umbenannt.\n</li></ul>"}, {"from": "FIG-8104920095fd3846", "to": "FIG-81b32993bfffabb0", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
